#!/usr/bin/env bash
# Create or update a PR with container image updates, and optionally arm
# auto-merge on it.
#
# Required env:
#   GH_TOKEN  - GitHub token for gh CLI
#   BRANCH    - branch name for the PR
#
# With AUTO_MERGE=true, also required:
#   DEFAULT_BRANCH     - the repository's default branch
#   GITHUB_REPOSITORY  - owner/repo (set by the runner)
#   GITHUB_REF_NAME    - the ref this run checked out (set by the runner)
#
# Reads: /tmp/pr_body.md (generated by check-image-updates.sh)

set -euo pipefail

AUTO_MERGE=${AUTO_MERGE:-false}

if [ "$AUTO_MERGE" = true ]; then
  # The branch is the checked-out ref's tip plus the update, force-pushed. From
  # any other ref that would publish the whole ref as an update and merge it.
  [ "$GITHUB_REF_NAME" = "$DEFAULT_BRANCH" ] || {
    echo "::error::refusing to auto-merge from ${GITHUB_REF_NAME}; only ${DEFAULT_BRANCH} may drive it." >&2
    exit 1
  }

  # With no required check GitHub considers the PR mergeable the moment it
  # opens, and gh then merges it outright instead of arming auto-merge.
  protection_checks=$(gh api "repos/${GITHUB_REPOSITORY}/branches/${DEFAULT_BRANCH}" \
    --jq '.protection.required_status_checks.contexts // [] | length')
  ruleset_checks=$(gh api "repos/${GITHUB_REPOSITORY}/rules/branches/${DEFAULT_BRANCH}" \
    --jq '[.[] | select(.type == "required_status_checks")] | length')
  [ "$protection_checks" -gt 0 ] || [ "$ruleset_checks" -gt 0 ] || {
    echo "::error::${DEFAULT_BRANCH} requires no status check, so auto-merge would land the update unchecked." >&2
    exit 1
  }
fi

git config user.name "github-actions[bot]"
git config user.email "41898282+github-actions[bot]@users.noreply.github.com"

# --head matches a branch name across forks; only a PR from this repo counts.
find_pr() {
  gh pr list --head "$BRANCH" --state open --json number,isCrossRepository \
    --jq '[.[] | select(.isCrossRepository == false)] | .[0].number // empty'
}

EXISTING_PR=$(find_pr)

git checkout -B "$BRANCH"
git add -u
git commit -m "chore: update container images"
HEAD_SHA=$(git rev-parse HEAD)

# Re-pushing an identical update every day would restart the PR's checks.
if [ -n "$EXISTING_PR" ] && git fetch --quiet origin "$BRANCH" 2>/dev/null &&
   [ "$(git rev-parse 'FETCH_HEAD^{tree}')" = "$(git rev-parse 'HEAD^{tree}')" ]; then
  HEAD_SHA=$(git rev-parse FETCH_HEAD)
  PR=$EXISTING_PR
  PUSHED=false
  echo "PR #$PR already carries these updates"
else
  git push --force origin "$BRANCH"
  PUSHED=true
  if [ -n "$EXISTING_PR" ]; then
    gh pr edit "$EXISTING_PR" --body-file /tmp/pr_body.md
    PR=$EXISTING_PR
    echo "Updated existing PR #$PR"
  else
    gh pr create \
      --title "chore: update container images" \
      --body-file /tmp/pr_body.md
    PR=$(find_pr)
    echo "Created PR #$PR"
  fi
fi

if [ "$AUTO_MERGE" = true ]; then
  # Pinned to the head pushed here: gh merges outright when GitHub already
  # considers the PR mergeable, and then takes whatever the head is.
  gh pr merge "$PR" --auto --merge --match-head-commit "$HEAD_SHA" || true
  state=$(gh pr view "$PR" --json state,autoMergeRequest \
    --jq 'if .autoMergeRequest then "armed" elif .state == "MERGED" then "merged" else "" end')
  [ -n "$state" ] || {
    echo "::error::could not arm auto-merge on PR #$PR; the update will wait for a manual merge." >&2
    exit 1
  }
  echo "PR #$PR: $state"

  # An armed PR whose checks failed, or that a rule blocks, stays armed and
  # open; a run that pushed nothing restarts nothing, so it must say so.
  if [ "$state" = armed ] && [ "$PUSHED" = false ]; then
    # shellcheck disable=SC2016 # $results and $pending are jq variables
    stuck=$(gh pr view "$PR" --json mergeStateStatus,statusCheckRollup --jq '
      [.statusCheckRollup[] | .conclusion // .state // ""] as $results
      | [.statusCheckRollup[] | select((.status // "COMPLETED") != "COMPLETED" or .state == "PENDING" or .state == "EXPECTED")] as $pending
      | if any($results[]; IN("FAILURE", "CANCELLED", "TIMED_OUT", "ACTION_REQUIRED", "STARTUP_FAILURE", "ERROR"))
          then "a check on it failed"
        elif .mergeStateStatus == "BLOCKED" and ($pending | length) == 0
          then "it is blocked with no check pending"
        else "" end')
    [ -z "$stuck" ] || {
      echo "::error::PR #$PR is armed but will not merge: ${stuck}." >&2
      exit 1
    }
  fi
fi
